    dist = [float('inf')] * n
    dist[s] = 0  # Starting node has distance 0

    # Use a priority queue to process nodes in order of increasing distance
    import heapq
    heap = []
    heapq.heappush(heap, (0, s))

    # Process nodes until the queue is empty
    while heap:
        current_dist, current_node = heapq.heappop(heap)

        # Check if current_dist is the smallest known distance
        if current_dist > dist[current_node]:
            continue

        # Explore all neighbors of current_node
        for neighbor in range(n):
            if neighbor == current_node:
                continue
            if dist[neighbor] > current_dist:
                new_dist = current_dist + 1
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(heap, (new_dist, neighbor))

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]

